import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PyramidZoomProps = Record<string, any>;

const CANVAS_WIDTH = 1000;
const CANVAS_HEIGHT = 1000;
const PYRAMID_TOP_Y = 50;
const PYRAMID_HEIGHT = 900;
const PYRAMID_CENTER_X = 500;

// Geometry Constants
const APEX_OFFSET = 0; // Changed to 0 to create a sharp apex (true pyramid)
const PYRAMID_SLOPE = 0.85; // Increased from 0.52 to 0.85 to widen the pyramid for text visibility

// Helper to calculate trapezoid points
const getTrapezoidPoints = (yStart: number, height: number, totalHeight: number) => {
  const yTop = yStart;
  const yBottom = yStart + height;
  
  // Calculate relative Y from virtual tip
  // Adding APEX_OFFSET effectively starts the pyramid lower down the cone,
  // resulting in a truncated pyramid (frustum) with a wider top.
  const relYTop = yTop - PYRAMID_TOP_Y + APEX_OFFSET;
  const relYBottom = yBottom - PYRAMID_TOP_Y + APEX_OFFSET;
  
  const xOffsetTop = relYTop * PYRAMID_SLOPE;
  const xOffsetBottom = relYBottom * PYRAMID_SLOPE;
  
  return [
    [PYRAMID_CENTER_X - xOffsetTop, yTop], // Top Left
    [PYRAMID_CENTER_X + xOffsetTop, yTop], // Top Right
    [PYRAMID_CENTER_X + xOffsetBottom, yBottom], // Bottom Right
    [PYRAMID_CENTER_X - xOffsetBottom, yBottom]  // Bottom Left
  ];
};

const pointsToString = (points: number[][]) => {
  return points.map(p => `${p[0]},${p[1]}`).join(" ");
};

const PyramidZoom: React.FC<PyramidZoomProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 12,
  
  primaryColor = "#CFFF3F", // Neon Green
  secondaryColor = "#111111", // Dark bg match
  textColorOnPrimary = "#111111",
  textColorOnSecondary = "#CFFF3F",
  
  level1Title = "3%",
  level1Subtitle = "BUYING NOW",
  
  level2Title = "17%",
  level2Subtitle = "Information Gathering Mode",
  
  level3Title = "20%",
  level3Subtitle = "Problem Aware",
  
  level4Title = "60%",
  level4Subtitle = "Not Problem Aware",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // -- GEOMETRY CALCULATIONS --
  // Adjusted ratios to match the reference image better (Top is larger)
  const ratios = [0.22, 0.22, 0.22, 0.34]; 
  const gap = 6; // Vertical gap between shapes
  
  // Calculate shapes
  const shapes = useMemo(() => {
    let currentY = PYRAMID_TOP_Y;
    return ratios.map((ratio, index) => {
      const h = PYRAMID_HEIGHT * ratio;
      const shapeHeight = h - gap;
      const points = getTrapezoidPoints(currentY, shapeHeight, PYRAMID_HEIGHT);
      const centerY = currentY + shapeHeight / 2;
      
      // Calculate width available at the vertical center of the shape
      // points[1][0] is TopRight X, points[0][0] is TopLeft X
      const topWidth = points[1][0] - points[0][0];
      const bottomWidth = points[2][0] - points[3][0];
      const centerWidth = (topWidth + bottomWidth) / 2;
      
      // Update Y for next shape
      currentY += h;
      
      return { points, centerY, index, centerWidth };
    });
  }, [ratios]);

  // -- CAMERA ANIMATION LOGIC --
  const progress = frame / totalFrames;

  const baseScale = Math.min(width, height) / 1000;
  
  // Adjusted sequence: Start -> L1 -> L2 -> L3 -> L4 -> End
  const targets = [
    { x: 500, y: 500, s: 0.5 },               // 0. Full View
    { x: 500, y: shapes[0].centerY, s: 2.4 }, // 1. Level 1
    { x: 500, y: shapes[1].centerY, s: 2.0 }, // 2. Level 2
    { x: 500, y: shapes[2].centerY, s: 1.6 }, // 3. Level 3
    { x: 500, y: shapes[3].centerY, s: 1.0 }, // 4. Level 4
    { x: 500, y: 500, s: 0.5 },               // 5. End Full View
  ];

  // Evenly distributed timing points for a linear narrative flow
  const timePoints = [
    0, 0.05,    // Hold Start
    0.15, 0.25, // Move to L1 & Hold
    0.35, 0.45, // Move to L2 & Hold
    0.55, 0.65, // Move to L3 & Hold
    0.75, 0.85, // Move to L4 & Hold
    0.95, 1.0   // Move to End & Hold
  ];
  
  const camX = interpolate(progress, timePoints, [
    targets[0].x, targets[0].x,
    targets[1].x, targets[1].x,
    targets[2].x, targets[2].x,
    targets[3].x, targets[3].x,
    targets[4].x, targets[4].x,
    targets[5].x, targets[5].x
  ], { 
    easing: Easing.inOut(Easing.ease),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  const camY = interpolate(progress, timePoints, [
    targets[0].y, targets[0].y,
    targets[1].y, targets[1].y,
    targets[2].y, targets[2].y,
    targets[3].y, targets[3].y,
    targets[4].y, targets[4].y,
    targets[5].y, targets[5].y
  ], { 
    easing: Easing.inOut(Easing.ease),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  const camScale = interpolate(progress, timePoints, [
    targets[0].s, targets[0].s,
    targets[1].s, targets[1].s,
    targets[2].s, targets[2].s,
    targets[3].s, targets[3].s,
    targets[4].s, targets[4].s,
    targets[5].s, targets[5].s
  ], { 
    easing: Easing.inOut(Easing.ease),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp" 
  });
  
  const finalScale = camScale * baseScale;
  const translateX = (width / 2) - (camX * finalScale);
  const translateY = (height / 2) - (camY * finalScale);

  // -- CONTENT DATA MAPPING --
  const content = [
    { title: level1Title, subtitle: level1Subtitle },
    { title: level2Title, subtitle: level2Subtitle },
    { title: level3Title, subtitle: level3Subtitle },
    { title: level4Title, subtitle: level4Subtitle },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <div
        style={{
          transform: `translate(${translateX}px, ${translateY}px) scale(${finalScale})`,
          transformOrigin: "0 0", 
          width: CANVAS_WIDTH,
          height: CANVAS_HEIGHT,
          position: "absolute",
          willChange: "transform",
        }}
      >
        <svg
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          viewBox={`0 0 ${CANVAS_WIDTH} ${CANVAS_HEIGHT}`}
          style={{ overflow: "visible" }}
        >
          {shapes.map((shape, i) => {
            const isTop = i === 0;
            // Calculate a safe width for text (85% of center width) to prevent spilling
            const textBoxWidth = Math.max(shape.centerWidth * 0.9, 40);
            
            return (
              <g key={i}>
                <polygon
                  points={pointsToString(shape.points)}
                  fill={isTop ? primaryColor : secondaryColor}
                  stroke={primaryColor}
                  strokeWidth={isTop ? 0 : 8}
                  strokeLinejoin="round"
                />
                
                {/* Text Group */}
                <g transform={`translate(${PYRAMID_CENTER_X}, ${shape.centerY})`}>
                   {/* Title (Percentage) */}
                  <text
                    x="0"
                    y={isTop ? -10 : -20}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    fill={isTop ? textColorOnPrimary : textColorOnSecondary}
                    style={{
                      fontFamily: "Montserrat",
                      fontWeight: 900,
                      fontSize: "60px",
                      letterSpacing: "-1px"
                    }}
                  >
                    {content[i].title}
                  </text>
                  
                  {/* Subtitle - Constrained Width */}
                  <foreignObject 
                    x={-textBoxWidth / 2} 
                    y={isTop ? 20 : 10}
                    width={textBoxWidth} 
                    height="200"
                  >
                    <div style={{
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "flex-start",
                      textAlign: "center",
                      fontFamily: "Montserrat",
                      fontWeight: 600,
                      fontSize: "32px",
                      color: isTop ? textColorOnPrimary : textColorOnSecondary,
                      lineHeight: 1.1,
                      width: "100%",
                      wordWrap: "break-word"
                    }}>
                      {content[i].subtitle}
                    </div>
                  </foreignObject>
                </g>
              </g>
            );
          })}
        </svg>
      </div>
      
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle, transparent 40%, rgba(0,0,0,0.3) 100%)",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default PyramidZoom;